(() => {
  const messageOrigin=location.protocol==='file:'?'*':location.origin;
  const style=document.createElement('link');style.rel='stylesheet';style.href='wireframes/exploration.css';document.head.append(style);
  const configScript=document.createElement('script');configScript.src='wireframes/handoff-config.js';document.head.append(configScript);
  const root=document.createElement('div');root.id='wireframes';root.className='wf-page';root.hidden=true;
  root.innerHTML=`<div class="wf-top"><strong>Mi Coins / STRUCTURE EXPLORATION</strong><a href="#audit">← 返回 UX Research</a></div><div class="wf-body"><section><div class="wf-kicker">01 / AI-assisted Wireframe Exploration</div><h1>先看懂奖励，还是先开始任务？</h1><p class="wf-description">同一组真实内容，两种信息架构。A 以奖励目标组织行动，B 优先支持正在进行和可参与的任务。以下均为可操作的灰阶低保真原型。</p><div class="wf-metadata"><span>Android · 392 × 871 dp</span><span>独立垂直滚动</span><span>AI 辅助结构探索</span><span>高保真由设计师在 Figma 完成</span></div><div class="wf-toolbar"><div class="wf-control-group"><span>画板模式</span><button data-mode="viewport" aria-pressed="true">871 dp 视窗</button><button data-mode="full" aria-pressed="false">完整长页</button></div><div class="wf-control-group"><span>文案预览</span><button data-lang="en" aria-pressed="true">English</button><button data-lang="ru" aria-pressed="false">Русский</button></div></div><div class="wf-compare"><article class="wf-scheme"><div class="wf-scheme-head"><div><div class="wf-kicker">A / 主方案</div><h2>Reward-driven</h2><p>VALUE → ACTION → PROGRESS</p></div><a href="wireframes/a.html" target="_blank" rel="noopener" data-standalone="A">单独打开 ↗</a></div><figure><div class="wf-frame-box"><iframe src="wireframes/a.html" title="方案 A：奖励驱动的 392dp 低保真原型" data-variant="A"></iframe><div class="wf-fold"><span>871 dp / 首屏边界</span></div></div><figcaption>奖励优先：大积分区 → 大小组合奖励卡 → 未选择的奖励目标 → 完整任务列表。</figcaption></figure></article><article class="wf-scheme"><div class="wf-scheme-head"><div><div class="wf-kicker">B / 备选方案</div><h2>Task-driven</h2><p>PROGRESS → ACTION → VALUE</p></div><a href="wireframes/b.html" target="_blank" rel="noopener" data-standalone="B">单独打开 ↗</a></div><figure><div class="wf-frame-box"><iframe src="wireframes/b.html" title="方案 B：任务驱动的 392dp 低保真原型" data-variant="B"></iframe><div class="wf-fold"><span>871 dp / 首屏边界</span></div></div><figcaption>任务优先：压缩积分区 → 当前 PUBG 进度 → 进行中 / 未开始 / 已完成任务 → 奖励 → 目标引导。</figcaption></figure></article></div><p class="wf-frame-hint">在每个画板内上下滚动，可浏览完整中心页；切换「完整长页」查看整页结构。画板内部始终按 392 dp 排版，窄屏展示时等比缩小；单独打开可直接操作。</p></section><section><div class="wf-kicker">Structure & Trade-offs</div><h2>两种优先级，而不只是模块换色。</h2><div class="wf-notes"><article class="wf-note"><h3>A / 奖励驱动</h3><div class="wf-order">导航 → 积分资产 → 奖励与目标 → 赚积分任务</div><p><b>潜在优点：</b>首屏呈现具体奖励，先建立收益感；目标选择后直接计算积分缺口，连接到任务行动。</p><p><b>潜在局限：</b>高频赚积分用户需下滑到任务区；奖励数量增加时，大小卡片的选择与优先级需要再验证。</p><p><b>结构选择：</b>800 ₽ / 8,000 积分卡为较大卡片，突出当前达到门槛的奖励；30,000 积分目标仍清晰可见。</p></article><article class="wf-note"><h3>B / 任务驱动</h3><div class="wf-order">导航 → 压缩积分资产 → 当前进度 → 任务 → 奖励 → 目标引导</div><p><b>潜在优点：</b>当前 50% 任务优先，减少继续任务的寻找成本；任务按参与状态排序，便于快速选择下一步。</p><p><b>潜在局限：</b>奖励价值出现较晚，新用户可能还未理解收益就看到任务；当前任务摘要与列表有少量重复。</p><p><b>结构选择：</b>顶部摘要支持直接继续 PUBG，列表保留全部原始任务；奖励及目标引导完整保留。</p></article></div><div class="wf-interactions"><div><b>01 / 奖励卡片</b><p>查看奖励 → 设为目标 → 显示余额、门槛、缺口与进度。达到门槛时优先展示兑换入口。</p></div><div><b>02 / 任务与状态</b><p>点击开始或继续 → 查看已有要求。弹层内可演示完成状态；不会自动增加余额。</p></div><div><b>03 / History</b><p>保留积分记录入口，打开说明占位。未提供的真实交易记录不编造。</p></div><div><b>04 / 交互边界</b><p>返回、信息、全部奖励与目标更换可操作。兑换仅为预览，不提交真实操作。</p></div></div><div class="wf-evidence"><b>业务内容核对与原型假设</b><ul><li>仅从原题取业务内容：余额 8,253；AliExpress 3,000 ₽ / 30,000 积分、AliExpress 800 ₽ / 8,000 积分、Recharge 20 ₽ / 200 积分。不引入 3,000 积分门槛。</li><li>30,000 − 8,253 = 21,747；8,000 与 200 积分奖励达到积分门槛。实际库存、地区和用户资格仍待确认。</li><li>前三项任务可核对 +100；MONOPOLY GO! 的奖励被底部裁切，保留「待核实」，不假定 +100。灰色勾选映射为 Completed 是原型解释；50% 保留为 In Progress，具体阶段未知。</li><li>保留首项任务的 23:43:00 截图计时信息，但不推断其含义、不作为真实倒计时运行。完成条件仅使用 Download and Activate。</li><li>原图商品副文案存在重复现金价值标注；线框采用各卡面可辨识面额，不把重复的 Cash value 3,000 ₽ 当作统一比例。可回看 <a href="assets/brief.png" target="_blank">原始任务书 ↗</a>。</li><li>粉色参考图只用于大积分区、大小奖励卡片与任务列表的布局节奏；未使用其签到、商品或积分机制。俄语为布局压力测试译文，正式文案仍需本地化复核。</li></ul></div></section><section id="wf-final"><div class="wf-kicker">02 / Designer-created High-Fidelity UI</div><h2>Final UI Design</h2><div id="wf-final-gallery" class="wf-final-gallery"><div class="wf-empty"><strong>等待设计师的 Figma 高保真作品</strong><p>接入你提供的 PNG 导出图片，以原图展示；此处不使用 AI 生成高保真，也不将低保真直接改色作为最终方案。</p></div></div></section><section id="wf-prototype"><div class="wf-handoff"><div><div class="wf-kicker">03 / Interactive Prototype</div><h2>Figma Prototype</h2><div id="wf-prototype-slot" class="wf-empty"><strong>等待 Figma Prototype 链接</strong><p>收到链接后，在此嵌入你本人完成的交互原型。</p></div></div><div><div class="wf-kicker">04 / View in Figma</div><h2>查看设计源文件</h2><div id="wf-file-slot" class="wf-empty"><span class="wf-disabled" role="link" aria-disabled="true">View in Figma · 待提供链接</span><p>目前没有最终文件链接，按钮保持不可用，不指向无关文件。</p></div></div></div><p class="wf-handoff-rule">后续接入仅展示原始导出图片、接入文件链接及嵌入原型，调整展示排版。高保真作品以设计师在 Figma 完成的版本为唯一视觉依据。</p></section><footer>AI-assisted Wireframe Exploration ≠ Designer-created High-Fidelity UI。原有研究内容保持不变；本区的交互均为低保真假设，并非产品现有完整规则。</footer></div>`;
  root.querySelectorAll('section[id]').forEach(section=>{const anchor=document.createElement('div');anchor.id=section.id;section.removeAttribute('id');section.prepend(anchor);});
  document.body.append(root);
  const navEntry=document.createElement('a');navEntry.href='#wireframes';navEntry.className='wf-nav-entry';navEntry.textContent='低保真探索';document.querySelector('header nav')?.append(navEntry);
  let mode='viewport',language='en';const heights={A:1800,B:2100};
  const frames=[...root.querySelectorAll('iframe[data-variant]')];
  function fitFrames(){if(root.hidden)return;frames.forEach(frame=>{const box=frame.parentElement;const available=box.parentElement.clientWidth;const scale=Math.min(1,available/392);const height=mode==='full'?heights[frame.dataset.variant]:871;box.style.width=`${392*scale}px`;box.style.height=`${height*scale}px`;frame.style.height=`${height}px`;frame.style.transform=`scale(${scale})`;box.querySelector('.wf-fold').style.top=`${871*scale}px`;box.querySelector('.wf-fold').style.display=mode==='full'?'block':'none';});}
  function route(){root.hidden=false;requestAnimationFrame(fitFrames);}
  root.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.mode){mode=button.dataset.mode;root.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));fitFrames();}if(button.dataset.lang){language=button.dataset.lang;root.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===language)));frames.forEach(frame=>frame.contentWindow.postMessage({type:'mi-wireframe-language',lang:language},messageOrigin));root.querySelectorAll('[data-standalone]').forEach(a=>a.href=`wireframes/${a.dataset.standalone.toLowerCase()}.html?lang=${language}`);}});
  addEventListener('message',event=>{if(event.origin!==location.origin)return;const frame=frames.find(f=>f.contentWindow===event.source);if(!frame)return;if(event.data?.type==='mi-wireframe-height'&&Number.isFinite(event.data.height)){const h=Math.max(871,Math.min(10000,event.data.height));if(heights[frame.dataset.variant]!==h){heights[frame.dataset.variant]=h;fitFrames();}}if(event.data?.type==='mi-wireframe-back')location.hash='audit';});
  frames.forEach(frame=>frame.addEventListener('load',()=>{frame.contentWindow.postMessage({type:'mi-wireframe-language',lang:language},messageOrigin);fitFrames();}));
  const resize=new ResizeObserver(fitFrames);root.querySelectorAll('.wf-scheme').forEach(e=>resize.observe(e));
  style.addEventListener("load",fitFrames);route();
  function handoff(){const config=window.MI_COINS_HANDOFF;if(!config)return;const validFigma=url=>{try{const u=new URL(url);return u.protocol==='https:'&&(u.hostname==='www.figma.com'||u.hostname==='figma.com');}catch{return false;}};if(config.images?.length&&root.querySelector('#wf-final-gallery')){const gallery=root.querySelector('#wf-final-gallery');gallery.replaceChildren();config.images.forEach(item=>{const image=document.createElement('img');image.src=item.src;image.alt=item.alt||'Designer-created high-fidelity UI';image.className='wf-final-image';gallery.append(image);});}if(validFigma(config.figmaFileUrl)&&root.querySelector('#wf-file-slot')){const slot=root.querySelector('#wf-file-slot');slot.replaceChildren();const link=document.createElement('a');link.className='wf-link';link.href=config.figmaFileUrl;link.target='_blank';link.rel='noopener';link.textContent='View in Figma ↗';slot.append(link);}if(validFigma(config.figmaPrototypeUrl)&&root.querySelector('#wf-prototype-slot')){const slot=root.querySelector('#wf-prototype-slot');slot.replaceChildren();slot.className='';const frame=document.createElement('iframe');frame.title='Designer-created Figma interactive prototype';frame.className='wf-prototype-embed';frame.src=`https://www.figma.com/embed?embed_host=share&url=${encodeURIComponent(config.figmaPrototypeUrl)}`;frame.allowFullscreen=true;slot.append(frame);}}
  configScript.addEventListener('load',handoff);handoff();
})();
